/* global Office, Excel */

// Valor por defecto si no se ha guardado ninguno previamente
let targetCellAddress = localStorage.getItem("targetExcelCell") || "A1";

Office.onReady((info) => {
  if (info.host === Office.HostType.Excel) {
    // Mantener el complemento activo en segundo plano
    Office.addin.setStartupBehavior(Office.StartupBehavior.load);

    // Obtener elementos de la interfaz HTML
    const input = document.getElementById("targetCellInput");
    const button = document.getElementById("saveCellBtn");
    const status = document.getElementById("statusMessage");

    // Colocar el valor actual guardado en la caja de texto
    if (input) {
      input.value = targetCellAddress;
    }

    // Configurar la acción al hacer clic en "Guardar celda destino"
    if (button) {
      button.onclick = () => {
        const newValue = input.value.trim();
        if (newValue) {
          targetCellAddress = newValue;
          localStorage.setItem("targetExcelCell", newValue);
          status.innerText = `✓ Guardado: Escribiendo en ${newValue}`;
          setTimeout(() => { 
            status.innerText = ""; 
          }, 3000);
        }
      };
    }

    // Activar la escucha de cambios de selección
    registerSelectionChangeListener();
  }
});

async function registerSelectionChangeListener() {
  await Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    sheet.onSelectionChanged.add(onSelectionChangeHandler);
    await context.sync();
  });
}

async function onSelectionChangeHandler(args) {
  await Excel.run(async (context) => {
    // 1. Obtener la dirección de la celda activa elegida por el usuario
    const activeCell = context.workbook.getActiveCell();
    activeCell.load("address");
    await context.sync();

    // 2. Determinar la celda/hoja destino según lo configurado
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    let targetRange;

    if (targetCellAddress.includes("!")) {
      // Si el usuario escribió un nombre de hoja con '!' (ej: "Datos!V1436")
      const parts = targetCellAddress.split("!");
      const targetSheetName = parts[0].replace(/'/g, ""); // Quitar comillas si las hay
      const cellRange = parts[1];
      
      const specificSheet = context.workbook.worksheets.getItem(targetSheetName);
      targetRange = specificSheet.getRange(cellRange);
    } else {
      // Si solo escribió la celda (ej: "V1436"), la escribe en la hoja actual
      targetRange = sheet.getRange(targetCellAddress);
    }

    // 3. Escribir la dirección activa dentro de la celda configurada
    targetRange.values = [[activeCell.address]];
    await context.sync();
  });
}